// Tests for ZFCMem and ZFCComprehension
// ═══════════════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════════════
// Rung-1 build: soundness gating + path-beta reduction + structural def-eq
// (docs/plans/CUBICAL_RUNG1_PROGRESS.md, Step 0 + Step 1)
// ═══════════════════════════════════════════════════════════════════════════

/// Env with `P : Prop` and two distinct proofs `pa, pb : P`.
fn env_with_two_proofs() -> Environment {
    use crate::env::Declaration;
    let mut env = Environment::new();
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("P"),
        level_params: vec![],
        type_: Expr::prop(),
    })
    .expect("P : Prop should register");
    let p = Expr::const_(Name::from_string("P"), vec![]);
    for proof in ["pa", "pb"] {
        env.add_decl(Declaration::Axiom {
            name: Name::from_string(proof),
            level_params: vec![],
            type_: p.clone(),
        })
        .expect("proof axiom should register");
    }
    env
}

/// SOUNDNESS (Step 0b): definitional proof irrelevance must be DISABLED in
/// Cubical mode — collapsing distinct proofs of a `Prop` is UIP, which is
/// inconsistent with univalence. It must still fire in Constructive mode.
#[test]
fn test_proof_irrel_gated_off_in_cubical_mode() {
    use crate::mode::CleanMode;
    let env = env_with_two_proofs();
    let pa = Expr::const_(Name::from_string("pa"), vec![]);
    let pb = Expr::const_(Name::from_string("pb"), vec![]);

    // Constructive (default, Lean-4-parity) mode: proof irrelevance identifies
    // any two proofs of the same Prop.
    let tc_constructive = TypeChecker::new(&env);
    assert!(
        tc_constructive.is_def_eq(&pa, &pb),
        "Constructive mode: proof irrelevance should make pa ≡ pb"
    );

    // Cubical mode: proof irrelevance is gated off; distinct proofs stay distinct.
    let tc_cubical = TypeChecker::with_mode(&env, CleanMode::Cubical);
    assert!(
        !tc_cubical.is_def_eq(&pa, &pb),
        "Cubical mode: proof irrelevance must NOT identify distinct proofs (UIP breaks univalence)"
    );
}

/// Step 1: path-beta `(<i> e) @ r  ↝  e[r/i]` at the WHNF level.
#[test]
fn test_cubical_path_beta_whnf_reduces() {
    use crate::mode::CleanMode;
    let env = Environment::new();
    let tc = TypeChecker::with_mode(&env, CleanMode::Cubical);

    // `<i> i` — path-lambda whose body is the bound interval variable.
    let mk_app = |endpoint: ExprKind| {
        let path_lam = Expr::from_kind(ExprKind::CubicalPathLam {
            body: std::sync::Arc::new(Expr::bvar(0)),
        });
        Expr::from_kind(ExprKind::CubicalPathApp {
            path: std::sync::Arc::new(path_lam),
            arg: std::sync::Arc::new(Expr::from_kind(endpoint)),
        })
    };

    let r0 = tc.whnf(&mk_app(ExprKind::CubicalI0));
    assert!(
        matches!(r0.kind(), ExprKind::CubicalI0),
        "(<i> i) @ i0 should path-beta to i0, got {r0:?}"
    );
    let r1 = tc.whnf(&mk_app(ExprKind::CubicalI1));
    assert!(
        matches!(r1.kind(), ExprKind::CubicalI1),
        "(<i> i) @ i1 should path-beta to i1, got {r1:?}"
    );
}

/// Step 1: a path application whose head is neutral (not a path-lam) must stay
