    let tc = TypeChecker::with_mode(&env, CleanMode::Cubical);
    let i0 = Expr::from_kind(ExprKind::CubicalI0);
    let i1 = Expr::from_kind(ExprKind::CubicalI1);
    assert!(tc.is_def_eq(&i0, &i0), "i0 ≡ i0");
