/// Cubical env with a genuinely interval-dependent type line `B : I → Type`
/// and `b : B i0`.
fn cubical_env_with_line_axiom() -> Environment {
    use crate::env::Declaration;
    use crate::mode::CleanMode;
    let mut env = Environment::with_mode(CleanMode::Cubical);
    let b_ty = Expr::pi(
        BinderInfo::Default,
        Expr::from_kind(ExprKind::CubicalInterval),
        Expr::type_(),
    );
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("B"),
        level_params: vec![],
        type_: b_ty,
    })
    .expect("B : I → Type should register");
    let bb = Expr::const_(Name::from_string("B"), vec![]);
    let b_at_i0 = Expr::app(bb, Expr::from_kind(ExprKind::CubicalI0));
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("b"),
        level_params: vec![],
        type_: b_at_i0,
    })
    .expect("b : B i0 should register");
    env
}

/// Transport along a CONSTANT type-family is the identity:
/// `transp (λ i. Prop) φ a ↝ a`.
#[test]
fn test_cubical_transp_constant_family_reduces_to_base() {
    use crate::mode::CleanMode;
    let env = env_with_base_prop_axiom();
    let tc = TypeChecker::with_mode(&env, CleanMode::Cubical);

    let base = Expr::const_(Name::from_string("base_prop"), vec![]);
    let family = Expr::lam(
        BinderInfo::Default,
        Expr::from_kind(ExprKind::CubicalInterval),
        Expr::prop(), // constant: body does not mention the interval var
    );
    let transp = Expr::from_kind(ExprKind::CubicalTransp {
        ty: std::sync::Arc::new(family),
        phi: std::sync::Arc::new(Expr::from_kind(ExprKind::CubicalI0)),
        base: std::sync::Arc::new(base),
    });

    let r = tc.whnf(&transp);
    assert!(
        matches!(r.kind(), ExprKind::Const(n, _) if *n == Name::from_string("base_prop")),
        "transp over a constant family must reduce to the base, got {r:?}"
    );
    // …and the kernel sees it definitionally: transp ≡ base.
    let base = Expr::const_(Name::from_string("base_prop"), vec![]);
    assert!(
        tc.is_def_eq(&transp, &base),
        "transp over a constant family must be def-eq to its base"
    );
}

/// A transport whose type-family is a neutral (non-lambda) line must stay stuck.
