/// A line that mentions the interval variable *syntactically* but WHNFs to a
/// constant type is still constant — transport reduces to the base.
#[test]
fn test_cubical_transp_reducible_constant_family() {
    use crate::mode::CleanMode;
    let env = env_with_base_prop_axiom();
    let tc = TypeChecker::with_mode(&env, CleanMode::Cubical);

    let base = Expr::const_(Name::from_string("base_prop"), vec![]);
    // line: λ i. ((λ _ : I. Prop) i) — body references i but β-reduces to Prop.
    let inner = Expr::lam(
        BinderInfo::Default,
        Expr::from_kind(ExprKind::CubicalInterval),
        Expr::prop(),
    );
    let body = Expr::app(inner, Expr::bvar(0));
    let family = Expr::lam(
        BinderInfo::Default,
        Expr::from_kind(ExprKind::CubicalInterval),
        body,
    );
    let transp = Expr::from_kind(ExprKind::CubicalTransp {
        ty: std::sync::Arc::new(family),
        phi: std::sync::Arc::new(Expr::from_kind(ExprKind::CubicalI0)),
        base: std::sync::Arc::new(base),
    });
    let r = tc.whnf(&transp);
    assert!(
        matches!(r.kind(), ExprKind::Const(n, _) if *n == Name::from_string("base_prop")),
        "transp over a reducible-constant family should reduce to base, got {r:?}"
    );
}

/// Cubical env for Pi-transport: `B : Type`, `D : I → Type`, `f : B → D i0`.
fn cubical_env_pi_transport() -> Environment {
    use crate::env::Declaration;
    use crate::mode::CleanMode;
    let mut env = Environment::with_mode(CleanMode::Cubical);
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("B"),
        level_params: vec![],
        type_: Expr::type_(),
    })
    .expect("B : Type");
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("D"),
        level_params: vec![],
        type_: Expr::pi(
            BinderInfo::Default,
            Expr::from_kind(ExprKind::CubicalInterval),
            Expr::type_(),
        ),
    })
    .expect("D : I → Type");
    // f : B → D i0
    let bb = Expr::const_(Name::from_string("B"), vec![]);
    let dd = Expr::const_(Name::from_string("D"), vec![]);
    let d_i0 = Expr::app(dd, Expr::from_kind(ExprKind::CubicalI0));
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("f"),
        level_params: vec![],
        type_: Expr::pi(BinderInfo::Default, bb, d_i0),
    })
    .expect("f : B → D i0");
    env
}

/// Transport in a Pi with a CONSTANT domain reduces (no backward coercion):
/// `transp (λ i. B → D i) i0 f ↝ λ (x:B). transp (λ i. D i) i0 (f x)`,
/// and the reduction is type-preserving.
#[test]
fn test_cubical_transp_pi_constant_domain() {
    use crate::mode::CleanMode;
    let env = cubical_env_pi_transport();
    let tc = TypeChecker::with_mode(&env, CleanMode::Cubical);

    let bb = Expr::const_(Name::from_string("B"), vec![]);
    let dd = Expr::const_(Name::from_string("D"), vec![]);
    let f = Expr::const_(Name::from_string("f"), vec![]);
    let i0 = || Expr::from_kind(ExprKind::CubicalI0);
    let interval = || Expr::from_kind(ExprKind::CubicalInterval);

    // line: λ i. (B → D i)   [inside the Pi codomain, i is BVar(1)]
    let line = Expr::lam(
        BinderInfo::Default,
        interval(),
        Expr::pi(
            BinderInfo::Default,
            bb.clone(),
            Expr::app(dd.clone(), Expr::bvar(1)),
        ),
    );
    let transp = Expr::from_kind(ExprKind::CubicalTransp {
        ty: std::sync::Arc::new(line),
        phi: std::sync::Arc::new(i0()),
        base: std::sync::Arc::new(f.clone()),
    });

    // The transport itself type-checks.
    let (transp_ty, _) = tc
        .infer_type_with_cert(&transp)
        .expect("transp (λ i. B → D i) i0 f should type-check");

    // It reduces to a lambda (the Pi rule fired).
    let r = tc.whnf(&transp);
    assert!(
        matches!(r.kind(), ExprKind::Lam(..)),
        "transp over a constant-domain Pi should reduce to a lambda, got {r:?}"
    );

    // Expected: λ (x:B). transp (λ i. D i) i0 (f x)
    let inner_line = Expr::lam(
        BinderInfo::Default,
        interval(),
        Expr::app(dd, Expr::bvar(0)),
    );
    let expected = Expr::lam(
        BinderInfo::Default,
        bb,
        Expr::from_kind(ExprKind::CubicalTransp {
            ty: std::sync::Arc::new(inner_line),
            phi: std::sync::Arc::new(i0()),
            base: std::sync::Arc::new(Expr::app(f, Expr::bvar(0))),
        }),
    );
    assert!(
        tc.is_def_eq(&r, &expected),
        "Pi-transport result mismatch.\n  got:      {r:?}\n  expected: {expected:?}"
    );

    // SOUNDNESS: the reduction is type-preserving — infer(result) ≡ infer(transp).
    let (r_ty, _) = tc
        .infer_type_with_cert(&r)
        .expect("the reduced lambda should type-check");
    assert!(
        tc.is_def_eq(&transp_ty, &r_ty),
        "Pi-transport must preserve type:\n  transp : {transp_ty:?}\n  result : {r_ty:?}"
    );
}

