// Rung-1: neutral path-endpoint reduction → function extensionality (funext)
// ═══════════════════════════════════════════════════════════════════════════

/// Cubical env for funext: `A : Type`, `B : A → Type`, `f g : Π(x:A). B x`,
/// `h : Π(x:A). Path (λ _. B x) (f x) (g x)`.
fn cubical_env_funext() -> Environment {
    use crate::env::Declaration;
    use crate::mode::CleanMode;
    let mut env = Environment::with_mode(CleanMode::Cubical);
    let axiom = |env: &mut Environment, name: &str, ty: Expr| {
        env.add_decl(Declaration::Axiom {
            name: Name::from_string(name),
            level_params: vec![],
            type_: ty,
        })
        .unwrap_or_else(|e| panic!("axiom {name} should register: {e:?}"));
    };

    axiom(&mut env, "A", Expr::type_());
    let a = Expr::const_(Name::from_string("A"), vec![]);
    axiom(
        &mut env,
        "B",
        Expr::pi(BinderInfo::Default, a.clone(), Expr::type_()),
    );
    let b = Expr::const_(Name::from_string("B"), vec![]);

    // Π(x:A). B x   (x is BVar(0) under the Pi binder)
    let pi_bx = Expr::pi(
        BinderInfo::Default,
        a.clone(),
        Expr::app(b.clone(), Expr::bvar(0)),
    );
    axiom(&mut env, "f", pi_bx.clone());
    axiom(&mut env, "g", pi_bx);
    let f = Expr::const_(Name::from_string("f"), vec![]);
    let g = Expr::const_(Name::from_string("g"), vec![]);

    // h : Π(x:A). Path (λ _:I. B x) (f x) (g x)
    //   under the Pi x-binder: x = BVar(0); inside the path's line i-binder x = BVar(1).
    let path_bx = Expr::from_kind(ExprKind::CubicalPath {
        ty: std::sync::Arc::new(Expr::lam(
            BinderInfo::Default,
            Expr::from_kind(ExprKind::CubicalInterval),
            Expr::app(b, Expr::bvar(1)),
        )),
        left: std::sync::Arc::new(Expr::app(f, Expr::bvar(0))),
        right: std::sync::Arc::new(Expr::app(g, Expr::bvar(0))),
    });
    axiom(&mut env, "h", Expr::pi(BinderInfo::Default, a, path_bx));
    env
}

/// Neutral path-endpoint reduction: `λ x. h x @ i0 ≡ f` and `λ x. h x @ i1 ≡ g`,
/// using `h x : Path _ (f x) (g x)`. This is the rule that makes `funext` work.
#[test]
fn test_cubical_path_endpoint_reduction() {
    use crate::mode::CleanMode;
    let env = cubical_env_funext();
    let tc = TypeChecker::with_mode(&env, CleanMode::Cubical);

    let a = Expr::const_(Name::from_string("A"), vec![]);
    let h = Expr::const_(Name::from_string("h"), vec![]);
    let f = Expr::const_(Name::from_string("f"), vec![]);
    let g = Expr::const_(Name::from_string("g"), vec![]);

    // E0 = λ (x:A). (h x @ i0)
    let e0 = Expr::lam(
        BinderInfo::Default,
        a.clone(),
        Expr::from_kind(ExprKind::CubicalPathApp {
            path: std::sync::Arc::new(Expr::app(h.clone(), Expr::bvar(0))),
            arg: std::sync::Arc::new(Expr::from_kind(ExprKind::CubicalI0)),
        }),
    );
    assert!(
        tc.is_def_eq(&e0, &f),
        "λ x. (h x @ i0) ≡ f via neutral path-endpoint reduction"
    );

    // E1 = λ (x:A). (h x @ i1)
    let e1 = Expr::lam(
        BinderInfo::Default,
        a,
        Expr::from_kind(ExprKind::CubicalPathApp {
            path: std::sync::Arc::new(Expr::app(h, Expr::bvar(0))),
            arg: std::sync::Arc::new(Expr::from_kind(ExprKind::CubicalI1)),
        }),
    );
    assert!(
        tc.is_def_eq(&e1, &g),
        "λ x. (h x @ i1) ≡ g via neutral path-endpoint reduction"
    );
}

/// **Milestone: function extensionality.** `funext h := <i> λ x. (h x @ i)`
/// type-checks at `Path (λ _. Π x. B x) f g` — i.e. `funext` holds in the
/// cubical kernel and its endpoints compute to `f` and `g`.
#[test]
fn test_cubical_funext_typechecks() {
    use crate::mode::CleanMode;
    let env = cubical_env_funext();
    let tc = TypeChecker::with_mode(&env, CleanMode::Cubical);

    let a = Expr::const_(Name::from_string("A"), vec![]);
    let b = Expr::const_(Name::from_string("B"), vec![]);
    let h = Expr::const_(Name::from_string("h"), vec![]);
    let f = Expr::const_(Name::from_string("f"), vec![]);
    let g = Expr::const_(Name::from_string("g"), vec![]);

    // funext = <i> λ (x:A). (h x @ i)
    //   under <i> then λx: x = BVar(0), i = BVar(1).
    let funext = Expr::from_kind(ExprKind::CubicalPathLam {
        body: std::sync::Arc::new(Expr::lam(
            BinderInfo::Default,
            a.clone(),
            Expr::from_kind(ExprKind::CubicalPathApp {
                path: std::sync::Arc::new(Expr::app(h, Expr::bvar(0))),
                arg: std::sync::Arc::new(Expr::bvar(1)),
            }),
        )),
    });

    let (ty, _) = tc
        .infer_type_with_cert(&funext)
        .expect("funext should type-check");

    // Expected: Path (λ _:I. Π(x:A). B x) f g
    let expected = Expr::from_kind(ExprKind::CubicalPath {
        ty: std::sync::Arc::new(Expr::lam(
            BinderInfo::Default,
            Expr::from_kind(ExprKind::CubicalInterval),
            Expr::pi(BinderInfo::Default, a, Expr::app(b, Expr::bvar(0))),
        )),
        left: std::sync::Arc::new(f),
        right: std::sync::Arc::new(g),
    });
    assert!(
        tc.is_def_eq(&ty, &expected),
        "funext : Path (Π x. B x) f g\n  inferred: {ty:?}"
    );
}

// ═══════════════════════════════════════════════════════════════════════════
// Rung-1: cubical Foundations building blocks (refl, ap/cong, transport·refl)
// — these type-check AND compute on the new path-beta + endpoint + transp core
// ═══════════════════════════════════════════════════════════════════════════

/// Env: `A B : Type`, `a b : A`, `p : Path (λ _. A) a b`, `fn : A → B`.
fn cubical_env_foundations() -> Environment {
    use crate::env::Declaration;
    use crate::mode::CleanMode;
    let mut env = Environment::with_mode(CleanMode::Cubical);
    let axiom = |env: &mut Environment, name: &str, ty: Expr| {
        env.add_decl(Declaration::Axiom {
            name: Name::from_string(name),
            level_params: vec![],
            type_: ty,
        })
        .unwrap_or_else(|e| panic!("axiom {name}: {e:?}"));
    };
    axiom(&mut env, "A", Expr::type_());
    axiom(&mut env, "Bt", Expr::type_());
    let a_ty = Expr::const_(Name::from_string("A"), vec![]);
    axiom(&mut env, "a", a_ty.clone());
    axiom(&mut env, "b", a_ty.clone());
    // p : Path (λ _. A) a b
    let line_const_a = Expr::lam(
        BinderInfo::Default,
        Expr::from_kind(ExprKind::CubicalInterval),
        a_ty.clone(),
    );
    let path_ty = Expr::from_kind(ExprKind::CubicalPath {
        ty: std::sync::Arc::new(line_const_a),
        left: std::sync::Arc::new(Expr::const_(Name::from_string("a"), vec![])),
        right: std::sync::Arc::new(Expr::const_(Name::from_string("b"), vec![])),
    });
    axiom(&mut env, "p", path_ty);
    // fn : A → Bt
    axiom(
        &mut env,
        "fn",
        Expr::pi(
            BinderInfo::Default,
            a_ty,
            Expr::const_(Name::from_string("Bt"), vec![]),
        ),
    );
    env
}

/// `refl a := <i> a : Path (λ _. A) a a`.
#[test]
fn test_cubical_foundations_refl() {
    use crate::mode::CleanMode;
    let env = cubical_env_foundations();
    let tc = TypeChecker::with_mode(&env, CleanMode::Cubical);
    let a = Expr::const_(Name::from_string("a"), vec![]);
    let a_ty = Expr::const_(Name::from_string("A"), vec![]);

    // refl a = <i> a
    let refl = Expr::from_kind(ExprKind::CubicalPathLam {
        body: std::sync::Arc::new(a.clone()),
    });
    let (ty, _) = tc.infer_type_with_cert(&refl).expect("refl type-checks");
    // expected: Path (λ _. A) a a
    let expected = Expr::from_kind(ExprKind::CubicalPath {
        ty: std::sync::Arc::new(Expr::lam(
            BinderInfo::Default,
            Expr::from_kind(ExprKind::CubicalInterval),
            a_ty,
        )),
        left: std::sync::Arc::new(a.clone()),
        right: std::sync::Arc::new(a),
    });
    assert!(
        tc.is_def_eq(&ty, &expected),
        "refl a : Path a a; got {ty:?}"
    );
}

/// **`ap`/`cong`:** `ap f p := <i> f (p @ i) : Path (f a) (f b)`.
/// Exercises path-beta + neutral endpoint reduction (`p @ i0 ≡ a`).
#[test]
fn test_cubical_foundations_ap_cong() {
    use crate::mode::CleanMode;
    let env = cubical_env_foundations();
    let tc = TypeChecker::with_mode(&env, CleanMode::Cubical);
    let p = Expr::const_(Name::from_string("p"), vec![]);
    let f = Expr::const_(Name::from_string("fn"), vec![]);
    let a = Expr::const_(Name::from_string("a"), vec![]);
    let b = Expr::const_(Name::from_string("b"), vec![]);
    let bt = Expr::const_(Name::from_string("Bt"), vec![]);

    // ap f p = <i> f (p @ i)    (i = BVar(0) under the path-lam)
    let ap = Expr::from_kind(ExprKind::CubicalPathLam {
        body: std::sync::Arc::new(Expr::app(
            f.clone(),
            Expr::from_kind(ExprKind::CubicalPathApp {
                path: std::sync::Arc::new(p),
                arg: std::sync::Arc::new(Expr::bvar(0)),
            }),
        )),
    });
    let (ty, _) = tc.infer_type_with_cert(&ap).expect("ap f p type-checks");

    // expected: Path (λ _. Bt) (f a) (f b)
    let expected = Expr::from_kind(ExprKind::CubicalPath {
        ty: std::sync::Arc::new(Expr::lam(
            BinderInfo::Default,
            Expr::from_kind(ExprKind::CubicalInterval),
            bt,
        )),
        left: std::sync::Arc::new(Expr::app(f.clone(), a)),
        right: std::sync::Arc::new(Expr::app(f, b)),
    });
    assert!(
        tc.is_def_eq(&ty, &expected),
        "ap f p : Path (f a) (f b); got {ty:?}"
    );
}

/// **`transport refl ≡ id`:** `transp (λ i. (<j> A) @ i) i0 a ↝ a`.
/// The line is constant only *after* path-beta — exercises the reductive
/// constant-family detection.
#[test]
fn test_cubical_foundations_transport_refl_is_identity() {
    use crate::mode::CleanMode;
    let env = cubical_env_foundations();
    let tc = TypeChecker::with_mode(&env, CleanMode::Cubical);
    let a = Expr::const_(Name::from_string("a"), vec![]);
    let big_a = Expr::const_(Name::from_string("A"), vec![]);

    // refl_Type = <j> A  : Path (λ _. Type) A A
    let refl_universe = Expr::from_kind(ExprKind::CubicalPathLam {
        body: std::sync::Arc::new(big_a),
    });
    // transport refl a = transp (λ i. refl_Type @ i) i0 a
    let line = Expr::lam(
        BinderInfo::Default,
        Expr::from_kind(ExprKind::CubicalInterval),
        Expr::from_kind(ExprKind::CubicalPathApp {
            path: std::sync::Arc::new(refl_universe),
            arg: std::sync::Arc::new(Expr::bvar(0)),
        }),
    );
    let transport = Expr::from_kind(ExprKind::CubicalTransp {
        ty: std::sync::Arc::new(line),
        phi: std::sync::Arc::new(Expr::from_kind(ExprKind::CubicalI0)),
        base: std::sync::Arc::new(a.clone()),
    });
    let r = tc.whnf(&transport);
    assert!(
        matches!(r.kind(), ExprKind::Const(n, _) if *n == Name::from_string("a")),
        "transport refl a should reduce to a, got {r:?}"
    );
    assert!(tc.is_def_eq(&transport, &a), "transport refl a ≡ a");
}

