// Rung-1 Step 4: hcomp reduction — total-cofibration rule
// ═══════════════════════════════════════════════════════════════════════════

/// `hcomp {A} {⊤} u base ↝ u i1` — the total-cofibration rule.
#[test]
fn test_cubical_hcomp_total_cofibration_reduces() {
    use crate::mode::CleanMode;
    let env = Environment::new();
    let tc = TypeChecker::with_mode(&env, CleanMode::Cubical);

    // hcomp {Type} {i1 = ⊤} (λ _:I. Prop) Prop  ↝  (λ _:I. Prop) i1 = Prop
    let hcomp = Expr::from_kind(ExprKind::CubicalHComp {
        ty: std::sync::Arc::new(Expr::type_()),
        phi: std::sync::Arc::new(Expr::from_kind(ExprKind::CubicalI1)),
        u: std::sync::Arc::new(Expr::lam(
            BinderInfo::Default,
            Expr::from_kind(ExprKind::CubicalInterval),
            Expr::prop(),
        )),
        base: std::sync::Arc::new(Expr::prop()),
    });
    // Type-checks (matches the existing hcomp type-check test shape, phi = i1).
    let (hcomp_ty, _) = tc
        .infer_type_with_cert(&hcomp)
        .expect("hcomp with total cofibration should type-check");
    // Reduces to u i1 = Prop.
    let r = tc.whnf(&hcomp);
    assert!(
        r.is_prop(),
        "hcomp over a total cofibration must reduce to u i1 (= Prop), got {r:?}"
    );
    // Type-preserving: infer(hcomp) ≡ infer(reduct).
    let (r_ty, _) = tc.infer_type_with_cert(&r).expect("reduct type-checks");
    assert!(
        tc.is_def_eq(&hcomp_ty, &r_ty),
        "hcomp reduction must preserve type"
    );
}

/// `hcomp {A} {⊥} u base ↝ base` — the empty-cofibration rule.
#[test]
fn test_cubical_hcomp_empty_cofibration_reduces_to_base() {
    use crate::mode::CleanMode;
    let env = env_with_base_prop_axiom();
    let tc = TypeChecker::with_mode(&env, CleanMode::Cubical);

    // hcomp {Prop} {i0 = ⊥} (λ _:I. base_prop) base_prop  ↝  base_prop (the floor)
    let bp = Expr::const_(Name::from_string("base_prop"), vec![]);
    let hcomp = Expr::from_kind(ExprKind::CubicalHComp {
        ty: std::sync::Arc::new(Expr::prop()),
        phi: std::sync::Arc::new(Expr::from_kind(ExprKind::CubicalI0)),
        u: std::sync::Arc::new(Expr::lam(
            BinderInfo::Default,
            Expr::from_kind(ExprKind::CubicalInterval),
            bp.clone(),
        )),
        base: std::sync::Arc::new(bp),
    });
    let r = tc.whnf(&hcomp);
    assert!(
        matches!(r.kind(), ExprKind::Const(n, _) if *n == Name::from_string("base_prop")),
        "hcomp over the empty cofibration must reduce to the floor (base), got {r:?}"
    );
}

/// `hcomp` over a NEUTRAL (undetermined) cofibration stays stuck — it must NOT be
/// reduced as if it were ⊥ or ⊤, since the variable could be either endpoint.
///
/// Uses a non-universe opaque element type `D` (with a point `dd : D`): for a
/// universe element type the (sound) Deliverable-A `hcomp`-in-`U` → `Glue` rule
/// now fires on a neutral extent, so the genuine "neutral cofib ⇏ ⊥/⊤" property is
/// tested where neither the universe→Glue nor the constructor-commutation rule
/// applies, leaving the only sound outcome a stuck `hcomp`.
#[test]
fn test_cubical_hcomp_neutral_cofibration_stays_stuck() {
    use crate::env::Declaration;
    use crate::mode::CleanMode;
    let mut env = Environment::with_mode(CleanMode::Cubical);
    // q : I  (a neutral interval variable)
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("q"),
        level_params: vec![],
        type_: Expr::from_kind(ExprKind::CubicalInterval),
    })
    .expect("q : I should register");
    // D : Type (opaque, non-universe element type) with a point dd : D.
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("D"),
        level_params: vec![],
        type_: Expr::type_(),
    })
    .expect("D : Type should register");
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("dd"),
        level_params: vec![],
        type_: Expr::const_(Name::from_string("D"), vec![]),
    })
    .expect("dd : D should register");
    let tc = TypeChecker::with_mode(&env, CleanMode::Cubical);

    let dd = Expr::const_(Name::from_string("dd"), vec![]);
    let hcomp = Expr::from_kind(ExprKind::CubicalHComp {
        ty: std::sync::Arc::new(Expr::const_(Name::from_string("D"), vec![])),
        phi: std::sync::Arc::new(Expr::const_(Name::from_string("q"), vec![])),
        u: std::sync::Arc::new(Expr::lam(
            BinderInfo::Default,
            Expr::from_kind(ExprKind::CubicalInterval),
            dd.clone(),
        )),
        base: std::sync::Arc::new(dd),
    });
    let r = tc.whnf(&hcomp);
    assert!(
        matches!(r.kind(), ExprKind::CubicalHComp { .. }),
        "hcomp over a neutral cofibration must stay stuck, got {r:?}"
    );
}

